        body: `テーマの予備知識は強力だが、使い方を誤ると大きな失点につながる。

■ 正しい使い方1：対立軸を先に想定する
論説を読み始めて「言葉」という語が出てきたら、「伝達の道具 ⇔ 世界の分節」という軸を頭に置く。すると「しかし」の後に何が来るかを予測しながら読める。予測が当たれば読む速度が上がる。

■ 正しい使い方2：抽象語の意味を思い出す道具にする
「分節」「疎外」「主体」「相対化」「アイデンティティ」など、入試論説の頻出語は意味を知らないと文が読めない。テーマ別に語彙を整理しておくと、初見の文章でも止まらない。
例）相対化＝絶対だと思っていたものを、他と比べて一つの見方にすぎないと捉え直すこと。

■ 危険な使い方：本文を読まずに選択肢を選ぶ
「科学論だから、科学を批判している選択肢が正解だろう」と決めつけると、逆張りの文章（科学の擁護）で全滅する。難関私立は、あえて典型と逆の主張をする文章を選ぶことがある。

■ 例）予測が外れる文章
「科学は不確実だという批判があるが、不確実さを数値として示せることこそ科学の強みである。占いは外れても不確実さを示さない。」
→ 典型の「科学懐疑」ではなく「科学擁護」。予測に引きずられると、「科学は万能ではない」という選択肢を選んでしまう。

■ 対策
①予測は「仮説」として持ち、本文の一行目から検証する。
②「しかし」「だが」が出たら、そこで予測を必ず更新する。
③選択肢を選ぶ前に、必ず本文の該当行を指で押さえる。

⚠ 注意：テーマ知識に頼りすぎる受験生は、易しい問題で高得点を取り、難しい問題で大きく崩れる。得点が安定しないのはこのパターンが多い。

★ ポイント：予備知識は自転車の補助輪と同じで、走り出しを助けるが、曲がるときは本文というハンドルに従う。`,
