本文（要約）：科学の説明は、いま手に入る証拠のもとで最もうまく説明できる仮説にすぎない。新しい証拠が出れば、説明は書き替えられる。だからといって科学が信用できないわけではない。むしろ、書き替えられる仕組みを持っていることこそが、科学の強さである。占いや神話は、外れても自らを書き替えない。

