        body: `二つの方式の中間として、多くの受験生に向く方式がある。

■ 方式C：傍線部マーク通読（推奨）
①設問を見て、傍線部の番号（①②③…）と、設問の型（理由・心情・内容）だけを確認する。所要30秒。
　例）問一＝理由／問二＝心情／問三＝内容／問四＝要旨
②本文を通読する。傍線部に来たら、その横に設問の型を一字で書く（理・心・内・要）。
③通読が終わったら設問に取りかかる。傍線部の横に型が書いてあるので、探す範囲がすぐ決まる。

■ この方式の利点
・設問文を全部読む必要がないので、時間のロスが30秒ですむ。
・読みながら「ここは理由が問われる」とわかるので、その前後を丁寧に読める。
・選択肢を読まないので先入観が生まれない。

■ 実際の記入例
本文の傍線部①の横に「理」、②の横に「心」、③の横に「内」と書く。設問に取りかかったとき、①なら直前3行、②なら直前の出来事と直後の行動、③なら直後1〜2行、と探す範囲が即座に決まる（s424参照）。

■ やってはいけないこと
・本文を二度通読する……時間が足りなくなる最大の原因。
・設問を解きながら本文を初めて読む……全体の流れが見えず、要旨設問で失点する。
・選択肢を先に読む……先入観による誤読を招く。

■ 例）60分・本文4000字の場合の時間
　設問の型確認　　30秒
　通読　　　　　　9分（傍線部に型を書きながら）
　設問処理　　　　14分30秒
　合計　　　　　　24分

⚠ 注意：小説では、傍線部の型確認に加えて「登場人物の名前」を先に確認しておくとよい。人物が三人以上出る小説では、誰が誰かを取り違えることが最大の失点要因になる。

★ ポイント：方式は一度決めたら本番まで変えない。演習で身体に入れた手順だけが、緊張した本番で機能する。`,
