        body: `知識は覚えるだけでは点にならない。「試験の形式で出されたときに答えられるか」を確かめる必要がある。

■ 確認の方法
①覚えるときは「読み→書き」の順ではなく「文の中で」覚える。
　×「転嫁＝てんか」
　○「責任を転嫁する」
　入試は必ず文の中で出題されるので、文ごと覚えれば同音異義語の判断もできる。

②書けるかどうかは、実際に書いて確かめる。頭の中で「書けるはず」と思っている字の3割は書けない。

③間違えた字だけをノートに集める。正解した字は二度と見ない。

■ 間違いノートの作り方
　左に問題文（責任をテンカする）
　右に正解（転嫁）
　その下に、間違えた理由（「転化」と書いた。転化は性質が変わること）
一週間後にもう一度解き、正解したら線を引いて消す。三回連続で正解したらノートから外す。

■ 実際の出題例と模範解答
問一　次の傍線部の漢字の読みを書きなさい。
　(1) 会議が紛糾する。　(2) 彼の言動は示唆に富む。　(3) 湖畔を散策する。　(4) 憂うべき事態だ。
　模範解答　(1)ふんきゅう　(2)しさ　(3)こはん　(4)うれ（うべき）

問二　次の傍線部のカタカナを漢字に直しなさい。
　(1) 事態をシュウシュウする。　(2) 会費をチョウシュウする。　(3) 名誉をキソンする。　(4) タイセイを立て直す。
　模範解答　(1)収拾　(2)徴収　(3)毀損（または棄損）　(4)態勢（文脈により体制・大勢）

■ (4)の判断
「タイセイを立て直す」なら、一時的な構えを整える意味なので「態勢」。「政治タイセイ」なら「体制」、「タイセイに影響はない」なら「大勢」。同音異義語は必ず文全体で判断する。

⚠ 注意：直前期に新しい漢字集を買ってはいけない。手持ちの教材の間違えた字だけを繰り返すほうが、確実に点になる。

★ ポイント：知識問題の目標は「満点」ではなく「落とさない」。すでに一度覚えたものを取りこぼさないことに集中する。`,
