        heading: '「に」と「で」の識別、活用の確認',
        body: `「に」と「で」は種類が多いが、判定の順序を決めれば処理できる。

■ 「に」の識別（順に試す）
①「な」に変えられるか → 形容動詞の活用語尾
　例）静かに歩く → 静かな　○　→ 形容動詞の一部
②直前が動詞の連用形で、あとに「なる」「する」が続くか → 格助詞（結果）
　例）先生になる
③「〜のときに」「〜の場所に」の意味か → 格助詞
　例）三時に会う／駅に行く
④切り離せない一語の一部か → 副詞の一部
　例）すでに／さらに／ついに

■ 「で」の識別（順に試す）
①「な」に変えられるか → 形容動詞の活用語尾
　例）静かである → 静かな　○
②「だ」に変えて文末にできるか → 断定の助動詞「だ」の連用形
　例）彼は学生で、私は社会人だ → 彼は学生だ　○
③手段・場所・原因を示すか → 格助詞
　例）バスで行く／公園で遊ぶ／病気で休む
④動詞の連用形に付いて前後をつなぐか → 接続助詞「て」の濁音化
　例）読んで理解する（読みて→読んで）

■ 実際の出題例と模範解答
問　次の傍線部と同じ用法のものを、あとのア〜エから一つ選べ。
　「彼はまだ帰らない。」
　ア　この本はおもしろくない。
　イ　彼女は何も言わない。
　ウ　今日は元気がない。
　エ　そんな話は聞いたことがない。
模範解答　イ
解説　「帰らない」は「帰らぬ」に置きかえられるので助動詞。イ「言わない」も「言わぬ」に置きかえられるので助動詞。ア「おもしろくない」は「おもしろくぬ」とは言えず、直前に「は」を入れて「おもしろくはない」と言えるので形容詞。ウ・エも「ないぬ」とは言えず形容詞。

■ 用言の活用
動詞の活用の種類（五段・上一段・下一段・カ行変格・サ行変格）と活用形（未然・連用・終止・連体・仮定・命令）は、表を白紙に書けるようにしておく。判別法は「ない」を付けたときの音。
　書く＋ない → 書かない（ア段）→ 五段活用
　起きる＋ない → 起きない（イ段）→ 上一段活用
　食べる＋ない → 食べない（エ段）→ 下一段活用
　来る・する → 変格活用

⚠ 注意：識別問題では、選択肢の中に「同じ品詞だが用法が違うもの」が混ぜてある。品詞名まで一致させるのではなく、設問が「同じ用法」を求めているのか「同じ品詞」を求めているのかを確認する。

★ ポイント：文法は範囲が狭く、出題も偏っている。四つの識別と活用表だけで、文法の配点4点のうち3点は取れる。`,
