　敷居が高い……不義理をして訪ねにくいこと。（×高級すぎて入りにくい、が本来の意味ではない）
　情けは人のためならず……人に情けをかけることは、めぐりめぐって自分のためになる。（×甘やかすのは本人のためにならない）
　気が置けない……遠慮がいらない、気楽である。（×油断ならない）
