        heading: '三つの部品を埋める',
        body: `記述解答は、次の三つの部品でできている。

■ 部品1：主語（主体）
誰の話か、何についての話かを明示する。
　例）「筆者は」「『私』は」「地域の祭りは」「言葉は」
省略すると、採点者は誰の説明か判断できない。特に小説の心情記述では、主語を落とすと大きく減点される。

■ 部品2：中核（本文のキーワード）
本文の中の重要語を2語前後入れる。採点はキーワードの有無で行われることが多いので、ここが得点の中心になる。
　例）本文が「当事者」「観客」という語で祭りの変化を説明していれば、この2語を必ず入れる。

■ 部品3：文末
設問の要求に対応させる。
　「なぜか」「理由を答えよ」→「〜から。」「〜ため。」
　「どういうことか」→「〜ということ。」
　「どのような気持ちか」→「〜という気持ち。」
　「どのような様子か」→「〜という様子。」
文末が設問と合っていないだけで減点される。ここは知っていれば必ず守れる。

■ 組み立ての例
設問：傍線部「見せるための祭りは中身が入れかわっている」とあるが、それはなぜか。四十字以内で説明しなさい。

　部品1（主語）……地元の人が
　部品2（中核）……観光客に見せる行事になることで／当事者ではなくなる
　部品3（文末）……〜から。

模範解答：観光客に見せる行事になることで、地元の人が祭りの当事者ではなくなるから。（三十六字）

★ ポイント：この三部品を余白にメモしてから清書する。いきなり解答欄に書き始めると、途中で崩れて消しゴムを使うことになる。`,
