        heading: '書けないときの最低限',
        body: `内容がまったく思い浮かばないときでも、書ける部分がある。

■ 段階1：文末だけ書く
「〜から。」とだけ書いても点にはならないが、そこから逆算して「何が〜から、なのか」を考えられる。

■ 段階2：本文のキーワードを入れる
傍線部を含む段落から、重要そうな語を2語選んで入れる。設問と無関係でなければ、部分点が入ることがある。

■ 段階3：傍線部の言いかえを書く
理由がわからなくても、傍線部を自分の言葉で言いかえて書く。設問が「どういうことか」なら、これだけで半分の点になることもある。

■ 実際の答案例（段階別の得点）
設問：傍線部の理由を四十字以内で説明しなさい。（配点4点）

　白紙……0点
　「祭りが変わったから。」（十字）……1点（キーワード不足、内容不足）
　「祭りが観光客に見せるものへ変わったから。」（十九字）……2点（キーワード「観光客に見せる」あり）
　「観光客に見せる行事になることで、地元の人が祭りの当事者ではなくなるから。」（三十六字）……4点（キーワード二つ＋主語＋文末）

このように、書けば書いた分だけ点が入る。白紙だけが必ず0点である。

■ 注意すべきこと
・字数が指定の半分に満たないと、内容不足として減点される。四十字なら三十二字以上を目指す。
・本文と無関係なことを書くと0点になる。必ず本文のキーワードを含める。
・「〜と思う」「〜だろう」といった推量で終えない。断定の形で書く。

■ 演習の方法
過去問の記述問題を、次の手順で練習する。
　①設問文から文末を決める（10秒）
　②本文からキーワードを2語選ぶ（20秒）
　③主語を決める（5秒）
　④三つをつないで書く（60秒）
合計95秒。この時間で書ききる練習を10問続けると、本番で手が止まらなくなる。

⚠ 注意：記述の練習で最も大切なのは「完璧な答案を書くこと」ではなく「必ず何か書き終えること」である。まず時間内に書き切る癖をつけ、内容の精度はそのあとで上げる。

★ ポイント：記述は才能ではなく手続きである。三部品を埋める作業として扱えば、誰でも一定の点は取れる。`,
