        body: `作文（150〜200字の条件作文）は、次の五項目を確認する。合計60秒。

■ ①条件の充足（最優先）
公立入試の作文には、必ず条件が付いている。
　例）「二段落構成で書くこと」「資料から読み取ったことを第一段落に書くこと」「自分の体験を含めること」「百五十字以上二百字以内で書くこと」
条件を一つでも満たさないと大幅減点、または0点になる。設問文の条件に丸を付けてから書き始めるのが原則だが、見直しでも必ず確認する。

■ ②段落
指定された段落数になっているか。二段落指定なら、段落の切れ目（改行＋一字下げ）が一か所あるか。

■ ③字数
「百五十字以上二百字以内」なら、150〜200の範囲に収まっているか。原稿用紙型なら行数で概算できる（20字詰めなら8行目の途中〜10行目）。

■ ④誤字・脱字
特に、常用漢字で書くべき語をひらがなにしていないか。逆に、あやふやな漢字を無理に使って誤字になっていないか。書ける自信がない語は、ひらがなで書くほうが安全である（減点が小さい）。

■ ⑤原稿用紙の使い方
　・書き出しは一字下げる。
　・段落の最初も一字下げる。
　・句読点が行頭に来ないよう、前の行の最後のマスに文字と一緒に入れる。
　・「」は一マスずつ使う。
　・数字は漢数字で書く（縦書きの場合）。

■ 実際の点検例
条件：「資料から読み取れることを第一段落に書き、それについての自分の考えを第二段落に書くこと。百五十字以上二百字以内。」
点検
　①条件……第一段落に資料の内容あり○　第二段落に自分の考えあり○
　②段落……二段落○
　③字数……176字○
　④誤字……「意見をのべる」→常用漢字なので「述べる」に修正
　⑤原稿用紙……書き出し一字下げ○　句読点の位置○

⚠ 注意：作文で最も多い失点は「条件の見落とし」である。特に「自分の体験を含めて」という条件を忘れ、一般論だけで書いてしまうケースが多い。

★ ポイント：作文は内容の良し悪しより、条件をすべて満たしているかで点が決まる。見直しでも条件の確認を最優先にする。`,
